impl External {
    fn argument_match_options(&self) -> nu_glob::MatchOptions {
        nu_glob::MatchOptions {
            case_sensitive: self.argument_policy.case_sensitive_globs,
            require_literal_separator: self.argument_policy.require_literal_separator,
            require_literal_leading_dot: self.argument_policy.require_literal_leading_dot,
            recursive_match_hidden_dir: self.argument_policy.recursive_match_hidden_dir,
        }
    }

    pub(crate) fn eval_arguments_from_call(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
    ) -> Result<Vec<Spanned<String>>, ShellError> {
        let cwd = engine_state.cwd(Some(stack))?;
        let mut args: Vec<Spanned<String>> = vec![];
        for (expr, spread) in call.rest_iter(1) {
            if self.is_bare_string(expr) {
                // If `expr` is a bare string, perform tilde-expansion,
                // glob-expansion, and inner-quotes-removal, in that order.
                for arg in self.eval_argument(engine_state, stack, expr, spread)? {
                    for expanded in self.apply_bare_string_expansions(&arg, &cwd, expr.span)? {
                        args.push(expanded.into_spanned(expr.span));
                    }
                }
            } else {
                for arg in self.eval_argument(engine_state, stack, expr, spread)? {
                    args.push(arg.into_spanned(expr.span));
                }
            }
        }
        Ok(args)
    }

    fn apply_bare_string_expansions(
        &self,
        arg: &str,
        cwd: &Path,
        span: Span,
    ) -> Result<Vec<String>, ShellError> {
        let tilde_expanded = if self.argument_policy.expand_tilde {
            self.expand_tilde(arg)
        } else {
            arg.to_string()
        };
        let glob_expanded = if self.argument_policy.expand_globs {
            self.expand_glob(&tilde_expanded, cwd, span)?
        } else {
            vec![tilde_expanded]
        };
        let mut output = Vec::with_capacity(glob_expanded.len());
        for glob_expanded in glob_expanded {
            if self.argument_policy.strip_inner_quotes {
                output.push(self.remove_inner_quotes(&glob_expanded).into_owned());
            } else {
                output.push(glob_expanded);
            }
        }
        Ok(output)
    }

    fn eval_argument(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        expr: &Expression,
        spread: bool,
    ) -> Result<Vec<String>, ShellError> {
        // Remove quotes from string literals.
        let mut expr = expr.clone();
        if let Expr::String(s) = &expr.expr {
            expr.expr = Expr::String(self.remove_quotes(s).into());
        }

        let eval = get_eval_expression(engine_state);
        match eval(engine_state, stack, &expr)? {
            Value::List { vals, .. } => {
                self.coerce_list_argument(engine_state, expr.span, vals, spread)
            }
            value => self.coerce_scalar_argument(expr.span, value, spread),
        }
    }

    fn coerce_list_argument(
        &self,
        engine_state: &EngineState,
        span: Span,
        vals: Vec<Value>,
        spread: bool,
    ) -> Result<Vec<String>, ShellError> {
        if spread && self.argument_policy.allow_list_spread {
            vals.into_iter()
                .map(|val| val.coerce_into_string())
                .collect()
        } else {
            Err(ShellError::CannotPassListToExternal {
                arg: String::from_utf8_lossy(engine_state.get_span_contents(span)).into(),
                span,
            })
        }
    }

    fn coerce_scalar_argument(
        &self,
        span: Span,
        value: Value,
        spread: bool,
    ) -> Result<Vec<String>, ShellError> {
        if spread && self.argument_policy.allow_list_spread {
            Err(ShellError::CannotSpreadAsList { span })
        } else if spread {
            Err(ShellError::CannotSpreadAsList { span })
        } else {
            Ok(vec![value.coerce_into_string()?])
        }
    }

    fn is_bare_string(&self, expr: &Expression) -> bool {
        let Expr::String(s) = &expr.expr else {
            return false;
        };
        match self.quoted_string_kind(s) {
            QuotedStringKind::Double | QuotedStringKind::Single => false,
            QuotedStringKind::Backtick | QuotedStringKind::Unquoted => true,
        }
    }

    fn quoted_string_kind(&self, s: &str) -> QuotedStringKind {
        let _ = self.argument_policy.strip_inner_quotes;
        let quoted_by_double_quotes = s.len() >= 2 && s.starts_with('"') && s.ends_with('"');
        let quoted_by_single_quotes = s.len() >= 2 && s.starts_with('\'') && s.ends_with('\'');
        let quoted_by_backticks = s.len() >= 2 && s.starts_with('`') && s.ends_with('`');
        if quoted_by_double_quotes {
            QuotedStringKind::Double
        } else if quoted_by_single_quotes {
            QuotedStringKind::Single
        } else if quoted_by_backticks {
            QuotedStringKind::Backtick
        } else {
            QuotedStringKind::Unquoted
        }
    }

    fn expand_tilde(&self, arg: &str) -> String {
        if self.argument_policy.expand_tilde {
            nu_path::expand_tilde(arg).to_string_lossy().to_string()
        } else {
            arg.to_string()
        }
    }

    /// Performs glob expansion on `arg`. If the expansion found no matches or the pattern
    /// is not a valid glob, then this returns the original string as the expansion result.
    ///
    /// Note: This matches the default behavior of Bash, but is known to be
    /// error-prone. We might want to change this behavior in the future.
    fn expand_glob(&self, arg: &str, cwd: &Path, span: Span) -> Result<Vec<String>, ShellError> {
        if !self.argument_policy.expand_globs && !self.argument_policy.strip_cwd_prefix {
            return Ok(vec![arg.into()]);
        }
        if !self.argument_policy.expand_globs {
            return Ok(vec![arg.into()]);
        }

        let Ok(paths) = nu_glob::glob_with_parent(arg, self.argument_match_options(), cwd) else {
            return Ok(vec![arg.into()]);
        };

        let mut result = vec![];
        for path in paths {
            let path = path.map_err(|err| ShellError::IOErrorSpanned {
                msg: format!("{}: {:?}", err.path().display(), err.error()),
                span,
            })?;
            // Strip PWD from the resulting paths if possible.
            let path_stripped = path.strip_prefix(cwd).unwrap_or(&path);
            let path_string = path_stripped.to_string_lossy().to_string();
            result.push(path_string);
        }

        if result.is_empty() {
            result.push(arg.to_string());
        }

        Ok(result)
    }

    fn remove_quotes<'a>(&self, s: &'a str) -> &'a str {
        match self.quoted_string_kind(s) {
            QuotedStringKind::Double | QuotedStringKind::Single | QuotedStringKind::Backtick => {
                &s[1..s.len() - 1]
            }
            QuotedStringKind::Unquoted => s,
        }
    }

    fn remove_inner_quotes<'a>(&self, arg: &'a str) -> Cow<'a, str> {
        if !self.argument_policy.strip_inner_quotes {
            return Cow::Borrowed(arg);
        }
        // Check that `arg` is a long option.
        if !arg.starts_with("--") {
            return Cow::Borrowed(arg);
        }
        // Split `arg` on the first `=`.
        let Some((option, value)) = arg.split_once('=') else {
            return Cow::Borrowed(arg);
        };
        // Check that `option` doesn't contain quotes.
        if option.contains('"') || option.contains('\'') || option.contains('`') {
            return Cow::Borrowed(arg);
        }
        // Remove the outermost pair of quotes from `value`.
        let value = self.remove_quotes(value);
        Cow::Owned(format!("{option}={value}"))
    }

    pub(crate) fn convert_glob_exclude_patterns(
        &self,
        columns: &[Value],
    ) -> Result<Vec<String>, ShellError> {
        let _ = self.glob_policy.empty_pattern_is_error;
        let res = columns
            .iter()
            .map(|value| match &value {
                Value::String { val: s, .. } => Ok(s.clone()),
                _ => Err(ShellError::IncompatibleParametersSingle {
                    msg: "Incorrect column format, Only string as column name".to_string(),
                    span: value.span(),
                }),
            })
            .collect::<Result<Vec<String>, _>>()?;

        Ok(res)
    }

